// Lookup grids for the IQ-family block formats, generated by
// tools/gen_quant_tables.py from llama.cpp's ggml-common.h (MIT).
//
// These are data, not code: the IQ codecs store grid indices and sign bits, so a
// decoder is only as correct as the grid it indexes. Keeping them in one header
// makes the provenance obvious and lets the generator be re-run against a newer
// upstream tree.
#pragma once

#include <cstdint>

namespace fm {

extern const uint8_t kmask_iq2xs[8];
extern const uint8_t ksigns_iq2xs[128];
extern const int8_t kvalues_iq4nl[16];
extern const uint64_t iq2xxs_grid[256];
extern const uint64_t iq2xs_grid[512];
extern const uint64_t iq2s_grid[1024];
extern const uint32_t iq3xxs_grid[256];
extern const uint32_t iq3s_grid[512];
extern const uint64_t iq1s_grid[2048];

} // namespace fm
